"""Очистка служебных следов python-docx в метаданных DOCX."""
from __future__ import annotations

import os
from pathlib import Path
import tempfile
from typing import Dict
from zipfile import ZIP_DEFLATED, ZipFile

from lxml import etree

CORE_PATH = "docProps/core.xml"
APP_PATH = "docProps/app.xml"

# Значения взяты из встроенного шаблона python-docx. Пользовательские значения,
# даже находящиеся в тех же элементах, не изменяются.
_CORE_DEFAULTS = {
    "{http://purl.org/dc/elements/1.1/}creator": {"python-docx"},
    "{http://purl.org/dc/elements/1.1/}description": {"generated by python-docx"},
    "{http://schemas.openxmlformats.org/package/2006/metadata/core-properties}lastModifiedBy": {
        "python-docx"
    },
    "{http://schemas.openxmlformats.org/package/2006/metadata/core-properties}keywords": {
        "python-docx"
    },
}
_APP_DEFAULTS = {
    "{http://schemas.openxmlformats.org/officeDocument/2006/extended-properties}Application": {
        "Microsoft Macintosh Word"
    },
    "{http://schemas.openxmlformats.org/officeDocument/2006/extended-properties}AppVersion": {
        "14.0000"
    },
}


def _clean_xml(data: bytes, defaults: Dict[str, set[str]]) -> bytes:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    root = etree.fromstring(data, parser=parser)
    changed = False
    for element in root.iter():
        values = defaults.get(element.tag)
        if values is not None and (element.text or "").strip() in values:
            element.text = None
            changed = True
    if not changed:
        return data
    return etree.tostring(
        root, encoding="UTF-8", xml_declaration=True, standalone=True
    )


def clear_python_docx_metadata(path: str | os.PathLike[str]) -> None:
    """Удаляет только известные подписи python-docx из core/app metadata.

    Архив переписывается атомарно. Остальные части DOCX и пользовательские
    значения метаданных сохраняются.
    """
    docx_path = Path(path)
    temporary_name = None
    try:
        with ZipFile(docx_path, "r") as source:
            with tempfile.NamedTemporaryFile(
                prefix=f".{docx_path.name}.", suffix=".tmp", dir=docx_path.parent,
                delete=False,
            ) as temporary:
                temporary_name = temporary.name
            with ZipFile(temporary_name, "w", compression=ZIP_DEFLATED) as target:
                for info in source.infolist():
                    data = source.read(info.filename)
                    if info.filename == CORE_PATH:
                        data = _clean_xml(data, _CORE_DEFAULTS)
                    elif info.filename == APP_PATH:
                        data = _clean_xml(data, _APP_DEFAULTS)
                    target.writestr(info, data)
        os.replace(temporary_name, docx_path)
        temporary_name = None
    finally:
        if temporary_name is not None:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass
